pagination_complete":true,"partial_sessions":[],"raw_one_minute_bar_count":5785,"represented_session_count":15,"represented_sessions":["2026-04-20","2026-04-21","2026-04-22","2026-04-23","2026-04-24","2026-04-27","2026-04-28","2026-04-29","2026-04-30","2026-05-01","2026-05-04","2026-05-05","2026-05-06","2026-05-07","2026-05-08"],"sector_benchmark":"XLK","sector_benchmark_completeness":1.0,"symbol":"PLTR","synchronization_completeness":1.0,"window":"dev-06"}]$coverage$::jsonb;
  v_result_count integer;
  v_failure_count integer;
  v_coverage_count integer;
  v_raw_count bigint;
  v_five_minute_count bigint;
  v_model_count bigint;
begin
  select
    experiment_id,
    methodology,
    rejection_criteria,
    cost_assumptions,
    universe_version,
    capital_scaling_authorized
  into
    v_experiment_id,
    v_methodology_before,
    v_rejection_criteria_before,
    v_cost_assumptions_before,
    v_universe_version_before,
    v_capital_scaling_before
  from private.trading_experiments
  where experiment_key = 'edge-discovery-v2-residual-downshock-rebound-v2.1'
  for update;

  if v_experiment_id is null or v_experiment_id <> '1e0e2f4a-6fef-4b2b-923f-630fa830c458'::uuid then
    raise exception 'RDR21 canonical experiment identity mismatch';
  end if;

  if (select manifest_hash from private.trading_experiments where experiment_id = v_experiment_id)
       is distinct from '92f8bad6362144805cc262c9188d199111a7f9c088caec56c0b0e6d579ffef7a' then
    raise exception 'RDR21 frozen manifest checksum mismatch';
  end if;

  if v_capital_scaling_before then
    raise exception 'RDR21 capital scaling unexpectedly authorized';
  end if;

  select jsonb_agg(to_jsonb(w) order by w.window_key)
  into v_protected_windows_before
  from private.trading_experiment_windows w
  where w.experiment_id = v_experiment_id
    and w.role in ('validation', 'holdout', 'quarantine');

  if (select count(*) from private.trading_experiment_windows
      where experiment_id = v_experiment_id and role = 'development') <> 6 then
    raise exception 'RDR21 expected six development windows';
  end if;

  if jsonb_array_length(v_coverage) <> 138 then
    raise exception 'RDR21 embedded coverage payload must contain 138 rows';
  end if;

  update private.trading_experiments
  set
    status = 'completed',
    started_at = '2026-09-26T20:19:01.390Z'::timestamptz,
    ended_at = '2026-09-26T20:56:54.814530Z'::timestamptz,
    completed_at = '2026-09-26T20:56:54.814530Z'::timestamptz,
    decision = 'DEVELOPMENT CORPUS FAIL; performance evaluation not run',
    conclusion = 'Development execution completed and stopped at the frozen corpus-quality gate. Two COST symbol-window records failed the 0.90 synchronization/model-availability threshold. Performance evaluation was not run; validation, holdout, and quarantine remained closed.',
    stage_reached = 'development_corpus_gate',
    survivor_state = 'corpus_quality_failed_pre_performance',
    terminal_decision = 'DEVELOPMENT CORPUS FAIL; performance evaluation not run',
    terminal_reason = 'corpus_quality_gate_failed_before_performance',
    sample_count = 128943,
    code_commit = '4f42fbcae33526659b6336ecd68808c53ad351f1',
    code_build_id = '9fe53699-1910-423f-8733-d071a3f2f8a3',
    artifact_location = 'github:anevum/alpaca-trader@9767f56d457302d496b1b5f3245ca5e8282f0e7c:research/artifacts/residual-downshock-rebound-v2.1/development-report-d408a930.json + railway:d408a930-6bb9-4f3b-b353-a832633f9cfd',
    report_reference = 'research/artifacts/residual-downshock-rebound-v2.1/development-report-d408a930.json',
    dataset_window = jsonb_set(
      dataset_window,
      '{development}',
      coalesce(dataset_window->'development', '{}'::jsonb) || jsonb_build_object(
        'opened', true,
        'executed', true,
        'data_fetched', true,
        'corpus_gate', 'FAIL',
        'performance_evaluated', false
      ),
      true
    ),
    metrics = metrics || jsonb_build_object(
      'run_started', true,
      'development_opened', true,
      'real_historical_results_collected', true,
      'real_historical_development_corpus_collected', true,
      'performance_evaluation_run', false,
      'performance_results_collected', false,
      'corpus_integrity_verdict', 'FAIL',
      'development_window_count', 6,
      'tradable_symbol_count', 23,
      'coverage_record_count', 138,
      'coverage_failure_count', 2,
      'missing_session_record_count', 0,
      'partial_session_record_count', 33,
      'pagination_complete_record_count', 138,
      'raw_one_minute_bar_count', 726277,
      'expected_five_minute_capacity', 156078,
      'represented_five_minute_observation_count', 155604,
      'expected_model_observation_capacity', 130065,
      'represented_model_observation_count', 128943,
      'source_page_count', 131,
      'configurations_defined', 6,
      'configurations_evaluated', 0,
      'selected_configuration_id', null,
      'validation_eligible', false,
      'validation_opened', false,
      'holdout_opened', false,
      'quarantine_accessed', false,
      'latest_performance_date_accessed', '2026-05-08',
      'canonicalized_at', '2026-09-27T00:48:59.457636Z',
      'provenance', jsonb_build_object(
        'report_declared_source_commit', '46c2de0d84c736b12f8a3bbeb64ef4ad1d5305cc',
        'actual_railway_source_commit', '4f42fbcae33526659b6336ecd68808c53ad351f1',
        'canonical_report_deployment_id', 'd408a930-6bb9-4f3b-b353-a832633f9cfd',
        'corroborating_report_deployment_id', 'ded64342-ee58-47db-8378-8bc8dfa8b6ba',
        'canonical_report_sha256', 'addf91840e07c94a564f5a00b0acf0ae3dfa6f2dda1d32b4dfd8a3250575e610',
        'semantic_payload_sha256', '71a7636b6d31694899fd55b2d2d6d4f6f8f07452ec9204bbe1c09b1fc34edaa9',
        'coverage_matrix_sha256', '91c34897e90e68e16d52f2a21eac428751d709d58cd886e0993a8529b9344fb1',
        'ratio_matrix_sha256', 'd2a4fb59417795989c59a5aba462cf34fad542346124f655f620189857605367',
        'evaluator_and_manifest_git_blobs_verified_identical', true
      )
    )
  where experiment_id = v_experiment_id;

  insert into private.trading_experiment_symbol_coverage (
    experiment_window_id,
    symbol,
    expected,
    present,
    bar_count,
    expected_session_count,
    represented_session_count,
    session_completeness,
    first_timestamp,
    last_timestamp,
    missing_sessions,
    pagination_complete,
    iex_bar_density_ratio,
    diagnostics
  )
  select
    w.experiment_window_id,
    c.value->>'symbol',
    true,
    true,
    (c.value->>'raw_one_minute_bar_count')::bigint,
    (c.value->>'expected_session_count')::integer,
    (c.value->>'represented_session_count')::integer,
    (c.value->>'expected_session_count')::integer = (c.value->>'represented_session_count')::integer
      and jsonb_array_length(c.value->'missing_sessions') = 0,
    (c.value->>'first_timestamp')::timestamptz,
    (c.value->>'last_timestamp')::timestamptz,
    coalesce(array(
      select value::date
      from jsonb_array_elements_text(c.value->'missing_sessions')
    ), '{}'::date[]),
    (c.value->>'pagination_complete')::boolean,
    null,
    c.value || jsonb_build_object(
      'expected_model_observation_count', (c.value->>'expected_session_count')::integer * 65,
      'model_observation_count', round(
        (c.value->>'model_availability_ratio')::numeric
        * (c.value->>'expected_session_count')::integer * 65
      )::bigint,
      'frozen_gate_threshold', 0.90,
      'source_report_sha256', 'addf91840e07c94a564f5a00b0acf0ae3dfa6f2dda1d32b4dfd8a3250575e610',
      'source_report_deployment_id', 'd408a930-6bb9-4f3b-b353-a832633f9cfd'
    )
  from jsonb_array_elements(v_coverage) c(value)
  join private.trading_experiment_windows w
    on w.experiment_id = v_experiment_id
   and w.window_key = c.value->>'window'
   and w.role = 'development'
  on conflict (experiment_window_id, symbol) do update
  set
    expected = excluded.expected,
    present = excluded.present,
    bar_count = excluded.bar_count,
    expected_session_count = excluded.expected_session_count,
    represented_session_count = excluded.represented_session_count,
    session_completeness = excluded.session_completeness,
    first_timestamp = excluded.first_timestamp,
    last_timestamp = excluded.last_timestamp,
    missing_sessions = excluded.missing_sessions,
    pagination_complete = excluded.pagination_complete,
    iex_bar_density_ratio = excluded.iex_bar_density_ratio,
    diagnostics = excluded.diagnostics;

  with aggregate_rows as (
    select
      c.value->>'window' as window_key,
      min((c.value->>'first_timestamp')::timestamptz) as first_timestamp,
      max((c.value->>'last_timestamp')::timestamptz) as last_timestamp,
      max((c.value->>'expected_session_count')::integer) as expected_session_count,
      max((c.value->>'represented_session_count')::integer) as represented_session_count,
      bool_and((c.value->>'pagination_complete')::boolean) as pagination_complete,
      min((c.value->>'synchronization_completeness')::numeric) as minimum_ratio,
      count(*) as coverage_record_count,
      count(*) filter (where not (c.value->>'gate_pass')::boolean) as failure_count,
      count(*) filter (where jsonb_array_length(c.value->'partial_sessions') > 0) as partial_record_count,
      sum(jsonb_array_length(c.value->'partial_sessions')) as partial_session_memberships,
      sum((c.value->>'raw_one_minute_bar_count')::bigint) as raw_bar_count,
      sum((c.value->>'five_minute_observation_count')::bigint) as five_minute_count,
      sum((c.value->>'expected_session_count')::bigint * 78) as expected_five_minute_capacity,
      sum((c.value->>'expected_session_count')::bigint * 65) as expected_model_capacity,
      sum(round(
        (c.value->>'model_availability_ratio')::numeric
        * (c.value->>'expected_session_count')::integer * 65
      )::bigint) as model_observation_count,
      coalesce(jsonb_agg(jsonb_build_object(
        'symbol', c.value->>'symbol',
        'synchronization_completeness', (c.value->>'synchronization_completeness')::numeric,
        'model_availability_ratio', (c.value->>'model_availability_ratio')::numeric
      )) filter (where not (c.value->>'gate_pass')::boolean), '[]'::jsonb) as failures
    from jsonb_array_elements(v_coverage) c(value)
    group by c.value->>'window'
  )
  update private.trading_experiment_windows w
  set
    status = case when a.failure_count = 0 then 'corpus_gate_pass' else 'corpus_gate_fail' end,
    present_symbols = w.expected_symbols,
    represented_session_count = a.represented_session_count,
    pagination_complete = a.pagination_complete,
    missing_sessions = '[]'::jsonb,
    completeness_basis = 'minimum synchronized/model availability ratio across expected symbol-window records',
    completeness_ratio = a.minimum_ratio,
    density_diagnostic = w.density_diagnostic || jsonb_build_object(
      'raw_one_minute_bar_count', a.raw_bar_count,
      'expected_five_minute_capacity', a.expected_five_minute_capacity,
      'represented_five_minute_observation_count', a.five_minute_count,
      'iex_bar_density_role', 'diagnostic_only'
    ),
    first_timestamp = a.first_timestamp,
    last_timestamp = a.last_timestamp,
    details = w.details || jsonb_build_object(
      'access', 'development_opened',
      'opened', true,
      'data_fetched', true,
      'corpus_gate_verdict', case when a.failure_count = 0 then 'PASS' else 'FAIL' end,
      'coverage_record_count', a.coverage_record_count,
      'coverage_failure_count', a.failure_count,
      'partial_session_record_count', a.partial_record_count,
      'partial_session_memberships', a.partial_session_memberships,
      'expected_model_observation_capacity', a.expected_model_capacity,
      'represented_model_observation_count', a.model_observation_count,
      'failing_symbol_windows', a.failures,
      'pagination_complete', a.pagination_complete,
      'performance_evaluated', false,
      'source_report_sha256', 'addf91840e07c94a564f5a00b0acf0ae3dfa6f2dda1d32b4dfd8a3250575e610',
      'source_report_deployment_id', 'd408a930-6bb9-4f3b-b353-a832633f9cfd'
    )
  from aggregate_rows a
  where w.experiment_id = v_experiment_id
    and w.role = 'development'
    and w.window_key = a.window_key;

  insert into private.trading_experiment_results (
    experiment_id,
    result_key,
    family,
    stage,
    period_id,
    cost_scenario,
    event_count,
    expectancy,
    profit_factor,
    worst_period_expectancy,
    threshold_floor,
    terminal_decision,
    terminal_reason_code,
    metrics
  ) values (
    v_experiment_id,
    'development:corpus-quality-gate',
    'corpus_integrity',
    'development',
    'dev-01..dev-06',
    null,
    null,
    null,
    null,
    null,
    0.90,
    'DEVELOPMENT CORPUS FAIL; performance evaluation not run',
    'corpus_quality_gate_failed_before_performance',
    jsonb_build_object(
      'corpus_integrity_verdict', 'FAIL',
      'performance_evaluation_run', false,
      'configurations_defined', 6,
      'configurations_evaluated', 0,
      'selected_configuration_id', null,
      'validation_eligible', false,
      'development_window_count', 6,
      'tradable_symbol_count', 23,
      'coverage_record_count', 138,
      'coverage_failure_count', 2,
      'raw_one_minute_bar_count', 726277,
      'expected_five_minute_capacity', 156078,
      'represented_five_minute_observation_count', 155604,
      'expected_model_observation_capacity', 130065,
      'represented_model_observation_count', 128943,
      'source_page_count', 131,
      'manifest_checksum', '92f8bad6362144805cc262c9188d199111a7f9c088caec56c0b0e6d579ffef7a',
      'canonical_report_sha256', 'addf91840e07c94a564f5a00b0acf0ae3dfa6f2dda1d32b4dfd8a3250575e610',
      'semantic_payload_sha256', '71a7636b6d31694899fd55b2d2d6d4f6f8f07452ec9204bbe1c09b1fc34edaa9',
      'access_audit', jsonb_build_object(
        'development_opened', true,
        'validation_opened', false,
        'holdout_opened', false,
        'quarantine_accessed', false,
        'latest_performance_date_accessed', '2026-05-08'
      )
    )
  )
  on conflict (experiment_id, result_key) do update
  set
    family = excluded.family,
    stage = excluded.stage,
    period_id = excluded.period_id,
    cost_scenario = excluded.cost_scenario,
    event_count = excluded.event_count,
    expectancy = excluded.expectancy,
    profit_factor = excluded.profit_factor,
    worst_period_expectancy = excluded.worst_period_expectancy,
    threshold_floor = excluded.threshold_floor,
    terminal_decision = excluded.terminal_decision,
    terminal_reason_code = excluded.terminal_reason_code,
    metrics = excluded.metrics;

  select decision_id
  into v_old_decision_id
  from private.trading_research_decisions
  where decision_key = 'residual-downshock-rebound-v2.1-selected'
  for update;

  if v_old_decision_id is null then
    raise exception 'RDR21 prior selected decision is missing';
  end if;

  insert into private.trading_research_decisions (
    decision_key,
    decided_at,
    status,
    decision_type,
    subject,
    conclusion,
    methodology_version,
    evidence,
    code_commit,
    deployment_id,
    supersedes_decision_id
  ) values (
    'residual-downshock-rebound-v2.1-development-corpus-fail',
    '2026-09-26T20:56:54.814530Z'::timestamptz,
    'final',
    'development_corpus_quality_failure',
    'Residual Downshock Rebound v2.1',
    'DEVELOPMENT CORPUS FAIL; performance evaluation not run',
    'residual-downshock-rebound-v2.1',
    jsonb_build_object(
      'executed', true,
      'development_opened', true,
      'corpus_integrity_verdict', 'FAIL',
      'performance_evaluation_run', false,
      'configurations_defined', 6,
      'configurations_evaluated', 0,
      'selected_configuration_id', null,
      'validation_eligible', false,
      'validation_opened', false,
      'holdout_opened', false,
      'quarantine_accessed', false,
      'coverage_record_count', 138,
      'coverage_failure_count', 2,
      'manifest_checksum', '92f8bad6362144805cc262c9188d199111a7f9c088caec56c0b0e6d579ffef7a',
      'report_declared_source_commit', '46c2de0d84c736b12f8a3bbeb64ef4ad1d5305cc',
      'actual_railway_source_commit', '4f42fbcae33526659b6336ecd68808c53ad351f1',
      'canonical_report_deployment_id', 'd408a930-6bb9-4f3b-b353-a832633f9cfd',
      'canonical_report_sha256', 'addf91840e07c94a564f5a00b0acf0ae3dfa6f2dda1d32b4dfd8a3250575e610',
      'semantic_payload_sha256', '71a7636b6d31694899fd55b2d2d6d4f6f8f07452ec9204bbe1c09b1fc34edaa9',
      'evaluator_and_manifest_git_blobs_verified_identical', true
    ),
    '4f42fbcae33526659b6336ecd68808c53ad351f1',
    'd408a930-6bb9-4f3b-b353-a832633f9cfd',
    v_old_decision_id
  )
  on conflict (decision_key) do update
  set
    decided_at = excluded.decided_at,
    status = excluded.status,
    decision_type = excluded.decision_type,
    subject = excluded.subject,
    conclusion = excluded.conclusion,
    methodology_version = excluded.methodology_version,
    evidence = excluded.evidence,
    code_commit = excluded.code_commit,
    deployment_id = excluded.deployment_id,
    supersedes_decision_id = excluded.supersedes_decision_id
  returning decision_id into v_new_decision_id;

  update private.trading_research_decisions
  set
    status = 'superseded',
    conclusion = 'Superseded by the completed DEVELOPMENT corpus-quality-gate decision. DEVELOPMENT executed, corpus integrity failed before performance evaluation, and validation remained locked.',
    evidence = evidence || jsonb_build_object(
      'executed', true,
      'development_opened', true,
      'corpus_integrity_verdict', 'FAIL',
      'performance_evaluation_run', false,
      'configurations_evaluated', 0,
      'selected_configuration_id', null,
      'validation_eligible', false,
      'validation_opened', false,
      'holdout_opened', false,
      'quarantine_accessed', false,
      'successor_decision_key', 'residual-downshock-rebound-v2.1-development-corpus-fail'
    ),
    superseded_by_decision_id = v_new_decision_id
  where decision_id = v_old_decision_id;

  insert into private.trading_research_decision_experiments (
    decision_id,
    experiment_id,
    evidence_role
  ) values (
    v_new_decision_id,
    v_experiment_id,
    'terminal_evidence'
  )
  on conflict (decision_id, experiment_id) do update
  set evidence_role = excluded.evidence_role;

  if (select methodology from private.trading_experiments where experiment_id = v_experiment_id)
       is distinct from v_methodology_before
     or (select rejection_criteria from private.trading_experiments where experiment_id = v_experiment_id)
       is distinct from v_rejection_criteria_before
     or (select cost_assumptions from private.trading_experiments where experiment_id = v_experiment_id)
       is distinct from v_cost_assumptions_before
     or (select universe_version from private.trading_experiments where experiment_id = v_experiment_id)
       is distinct from v_universe_version_before
     or (select capital_scaling_authorized from private.trading_experiments where experiment_id = v_experiment_id)
       is distinct from v_capital_scaling_before then
    raise exception 'RDR21 frozen methodology/risk/universe state changed';
  end if;

  if (select jsonb_agg(to_jsonb(w) order by w.window_key)
      from private.trading_experiment_windows w
      where w.experiment_id = v_experiment_id
        and w.role in ('validation', 'holdout', 'quarantine'))
      is distinct from v_protected_windows_before then
    raise exception 'RDR21 protected window state changed';
  end if;

  select
    count(*),
    count(*) filter (where not (c.diagnostics->>'gate_pass')::boolean),
    sum(c.bar_count),
    sum((c.diagnostics->>'five_minute_observation_count')::bigint),
    sum((c.diagnostics->>'model_observation_count')::bigint)
  into
    v_coverage_count,
    v_failure_count,
    v_raw_count,
    v_five_minute_count,
    v_model_count
  from private.trading_experiment_symbol_coverage c
  join private.trading_experiment_windows w
    on w.experiment_window_id = c.experiment_window_id
  where w.experiment_id = v_experiment_id
    and w.role = 'development';

  if v_coverage_count <> 138
     or v_failure_count <> 2
     or v_raw_count <> 726277
     or v_five_minute_count <> 155604
     or v_model_count <> 128943 then
    raise exception 'RDR21 canonical coverage totals failed verification';
  end if;

  if (select count(*) from private.trading_experiment_symbol_coverage c
      join private.trading_experiment_windows w
        on w.experiment_window_id = c.experiment_window_id
      where w.experiment_id = v_experiment_id
        and w.role <> 'development') <> 0 then
    raise exception 'RDR21 protected-stage coverage must remain absent';
  end if;

  if (select count(*) from private.trading_experiment_symbol_coverage c
      join private.trading_experiment_windows w
        on w.experiment_window_id = c.experiment_window_id
      where w.experiment_id = v_experiment_id
        and w.role = 'development'
        and not (c.diagnostics->>'gate_pass')::boolean
        and (w.window_key, c.symbol) not in (('dev-04', 'COST'), ('dev-06', 'COST'))) <> 0 then
    raise exception 'RDR21 unexpected coverage failure identity';
  end if;

  select count(*) into v_result_count
  from private.trading_experiment_results
  where experiment_id = v_experiment_id;

  if v_result_count <> 1
     or not exists (
       select 1
       from private.trading_experiment_results
       where experiment_id = v_experiment_id
         and result_key = 'development:corpus-quality-gate'
         and family = 'corpus_integrity'
         and event_count is null
         and expectancy is null
         and profit_factor is null
         and (metrics->>'configurations_evaluated')::integer = 0
         and metrics->'selected_configuration_id' = 'null'::jsonb
         and not (metrics->>'validation_eligible')::boolean
     ) then
    raise exception 'RDR21 result row must be corpus-only and pre-performance';
  end if;

  if exists (
    select 1
    from private.trading_research_decisions d
    join private.trading_research_decision_experiments de
      on de.decision_id = d.decision_id
    where de.experiment_id = v_experiment_id
      and d.status = 'selected_unexecuted'
  ) then
    raise exception 'RDR21 selected_unexecuted decision remains';
  end if;
end
$rhen$;
